const getRefreshTokenForUpdate = `-- name: GetRefreshTokenForUpdate :one
SELECT
    rt.id,
    rt.session_id,
    rt.expires_at,
    rt.used_at,
    s.user_id,
    s.client,
    s.revoked_at AS session_revoked_at,
    s.expires_at AS session_expires_at,
    s.created_at AS session_created_at,
    u.status AS user_status,
    u.email_verified_at AS user_email_verified_at
FROM refresh_tokens rt
JOIN auth_sessions s ON s.id = rt.session_id
JOIN users u ON u.id = s.user_id
WHERE rt.token_hash = $1
FOR UPDATE OF rt
`

type GetRefreshTokenForUpdateRow struct {
	ID                  uuid.UUID
	SessionID           uuid.UUID
	ExpiresAt           time.Time
	UsedAt              *time.Time
	UserID              uuid.UUID
	Client              string
	SessionRevokedAt    *time.Time
	SessionExpiresAt    time.Time
	SessionCreatedAt    time.Time
	UserStatus          string
	UserEmailVerifiedAt *time.Time
}

// Locks the token row so two concurrent refreshes can't both rotate it.
func (q *Queries) GetRefreshTokenForUpdate(ctx context.Context, tokenHash []byte) (GetRefreshTokenForUpdateRow, error) {
	row := q.db.QueryRow(ctx, getRefreshTokenForUpdate, tokenHash)
	var i GetRefreshTokenForUpdateRow
	err := row.Scan(
		&i.ID,
		&i.SessionID,
		&i.ExpiresAt,
		&i.UsedAt,
		&i.UserID,
		&i.Client,
		&i.SessionRevokedAt,
		&i.SessionExpiresAt,
		&i.SessionCreatedAt,
		&i.UserStatus,
		&i.UserEmailVerifiedAt,
	)
	return i, err
}

